// Normalise the API response and drop articles that were already delivered.
// Keys of delivered articles are stored in workflow static data by "Remember Sent Articles".
// Note: n8n only persists static data for production (active, trigger-started) executions,
// so manual test runs never mark anything as sent.
const body = $input.first().json;
if (!Array.isArray(body.data)) {
  throw new Error('Unexpected News API response: missing data[] array');
}
const staticData = $getWorkflowStaticData('global');
const alreadySent = new Set(staticData.sentKeys || []);
const inThisRun = new Set();
const fresh = [];
for (const a of body.data) {
  if (!a || !a.title || !a.url) continue;
  const key = a.uuid || a.url;
  if (alreadySent.has(key) || inThisRun.has(key)) continue;
  inThisRun.add(key);
  fresh.push({
    json: {
      key,
      title: String(a.title).trim(),
      url: a.url,
      source: a.source || '',
      publishedAt: a.published_at || null,
    },
  });
}
// Returning zero items ends the execution here: nothing new, nothing sent.
return fresh;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const articles = $input.all().map((item) => item.json);
const lines = articles.map((a, i) => {
  const source = a.source ? ` <i>(${esc(a.source)})</i>` : '';
  return `${i + 1}. <a href="${esc(a.url)}">${esc(a.title)}</a>${source}`;
});
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
let message = `<b>Daily News Roundup</b>\n\n${lines.join('\n')}\n\n<i>Source: TheNewsAPI.com, ${stamp} UTC</i>`;
// Telegram rejects messages longer than 4096 characters.
if (message.length > 4000) message = message.slice(0, 3990) + '\n...';
return [{ json: { message, articleKeys: articles.map((a) => a.key), totalHeadlines: articles.length } }];

// Runs only after Telegram accepted the message, so a failed send is retried next run.
const MAX_REMEMBERED = 500;
const staticData = $getWorkflowStaticData('global');
const keys = $('Format Digest').first().json.articleKeys || [];
const merged = [...new Set([...(staticData.sentKeys || []), ...keys])];
staticData.sentKeys = merged.slice(-MAX_REMEMBERED);
return [{
  json: {
    status: 'sent',
    headlinesSent: keys.length,
    rememberedKeys: staticData.sentKeys.length,
    executionTime: new Date().toISOString(),
  },
}];
